                code = emon.Port.CellsAt(ws, DDcode + ds);
                nb = emon.Port.CellsAt(ws, DDlen + ds);
                DfBits(ws, @out, code, nb);
                ex = DfDext[ds];
                if (ex > 0) {
                    DfBits(ws, @out, di - DfDbase[ds], ex);
                }
            }
            k += 1;
        }
        code = emon.Port.CellsAt(ws, DLcode + 256);
        nb = emon.Port.CellsAt(ws, DLlen + 256);
        DfBits(ws, @out, code, nb);
        return 0;
    }
    internal static int DfStored(emon.Port.Cells ws, emon.Port.Buf @out, int span) {
        // The body of a stored block: LEN, NLEN, then the bytes from the ring.
        int from = emon.Port.CellsAt(ws, DBstart);
        int k = 0;
        int v = 0;
        emon.Port.BufPush(@out, span & 255);
        emon.Port.BufPush(@out, ((span) >> (8)) & 255);
        emon.Port.BufPush(@out, (65535 - span) & 255);
        emon.Port.BufPush(@out, ((65535 - span) >> (8)) & 255);
        while (k < span) {
            v = emon.Port.CellsAt(ws, DRing + ((from + k) & 65535));
            emon.Port.BufPush(@out, v);
            k += 1;
        }
        return 0;
    }
    internal static int DfFlush(emon.Port.Cells ws, emon.Port.Buf @out, int end, int fin) {
        // Write the pending symbols as one block, of the type that costs the
        // fewest bits (ties: stored, fixed, dynamic), and start the next block.
        int span = end - emon.Port.CellsAt(ws, DBstart);
        int force = emon.Port.CellsAt(ws, DForce);
        int bc = emon.Port.CellsAt(ws, DBitcnt);
        int ty = 1;
        int best = 0;
        int elig = 0;
        int cs = 0;
        int cf = 0;
        int cd = 0;
        int i = 0;
        emon.Port.CellsSet(ws, DLfreq + 256, 1);
        DfLengths(ws, DLfreq, 286, 15, DLlen);
        DfLengths(ws, DDfreq, 30, 15, DDlen);
        DfPlan(ws);
        cd = DfCostDyn(ws);
        cf = DfCostFixed(ws);
        if (span <= 32768) {
            elig = 1;
            cs = 35 + ((8 * span) + ((8 - ((bc + 3) % 8)) % 8));
        }
        ty = 0;
        best = cs;
        if (elig == 0) {
            ty = 1;
            best = cf;
        }
        if (cf < best) {
            ty = 1;
            best = cf;
        }
        if (cd < best) {
            ty = 2;
            best = cd;
        }
        if (force == 2) {
            ty = 1;
        }
        if (force == 3) {
            ty = 2;
        }
        if ((force == 1) && (elig == 1)) {
            ty = 0;
        }
        DfBits(ws, @out, fin, 1);
        if (ty == 0) {
            DfBits(ws, @out, 0, 2);
            DfAlign(ws, @out);
            DfStored(ws, @out, span);
        } else {
            if (ty == 1) {
                DfBits(ws, @out, 1, 2);
                DfFixed(ws);
                DfCodes(ws, DLlen, DLcode, 288);
                DfCodes(ws, DDlen, DDcode, 30);
            } else {
                DfBits(ws, @out, 2, 2);
                DfCodes(ws, DLlen, DLcode, 286);
                DfCodes(ws, DDlen, DDcode, 30);
                DfCodes(ws, DCllen, DClcode, 19);
                DfHead(ws, @out);
            }
            DfEmit(ws, @out);
        }
        emon.Port.CellsSet(ws, DNsym, 0);
        emon.Port.CellsSet(ws, DBstart, end);
        while (i < 288) {
            emon.Port.CellsSet(ws, DLfreq + i, 0);
            i += 1;
        }
        i = 0;
        while (i < 32) {
            emon.Port.CellsSet(ws, DDfreq + i, 0);
            i += 1;
        }
        return 0;
    }
    internal static int DfCount(emon.Port.Cells ws, int at) {
        int f = emon.Port.CellsAt(ws, at);
        emon.Port.CellsSet(ws, at, f + 1);
        return 0;
    }
    internal static int DfSym(emon.Port.Cells ws, emon.Port.Buf @out, int sym, int end) {
        // Record one symbol (the input up to `end` is now covered). A literal is
        // 0..255; a match is length * 65536 + distance - 1. The 16,384th symbol
        // closes a block.
        int n = emon.Port.CellsAt(ws, DNsym);
        int li = 0;
        int ds = 0;
        emon.Port.CellsSet(ws, DSyms + n, sym);
        if (sym < 65536) {
            DfCount(ws, DLfreq + sym);
        } else {
            li = emon.Port.CellsAt(ws, DLsym + (sym / 65536));
            DfCount(ws, DLfreq + (257 + li));
            ds = DfDsym((sym & 65535) + 1);
            DfCount(ws, DDfreq + ds);
        }
        emon.Port.CellsSet(ws, DNsym, n + 1);
        if ((n + 1) == 16384) {
            DfFlush(ws, @out, end, 0);
        }
        return 0;
    }
    internal static int DfStep(emon.Port.Cells ws, emon.Port.Buf @out) {
        // Decide position p = D_POS: a literal, or a match (taking the match of
        // p+1 instead, after a literal for p, when that one is strictly longer).
        int p = emon.Port.CellsAt(ws, DPos);
        int av = emon.Port.CellsAt(ws, DAvail);
        int ml1 = av - p;
        int ml2 = 0;
        int m1 = 0;
        int m2 = 0;
        int st = p;
        int mm = 0;
        int ln = 0;
        int en = 0;
        int q = 0;
        int v = 0;
        if (ml1 > 258) {
            ml1 = 258;
        }
        m1 = DfFind(ws, p, ml1);
        if (m1 == 0) {
            v = emon.Port.CellsAt(ws, DRing + (p & 65535));
            if ((p + 2) < av) {
                DfInsert(ws, p);
            }
            emon.Port.CellsSet(ws, DIns, p + 1);
            emon.Port.CellsSet(ws, DPos, p + 1);
            DfSym(ws, @out, v, p + 1);
            return 0;
        }
        DfInsert(ws, p);
        emon.Port.CellsSet(ws, DIns, p + 1);
        ml2 = av - (p + 1);
        if (ml2 > 258) {
            ml2 = 258;
        }
        m2 = DfFind(ws, p + 1, ml2);
        mm = m1;
        if ((m2 / 65536) > (m1 / 65536)) {
            v = emon.Port.CellsAt(ws, DRing + (p & 65535));
            DfSym(ws, @out, v, p + 1);
            st = p + 1;
            mm = m2;
        }
        ln = mm / 65536;
        en = st + ln;
        DfSym(ws, @out, mm, en);
        q = emon.Port.CellsAt(ws, DIns);
        while (q < en) {
            if ((q + 2) < av) {
                DfInsert(ws, q);
            }
            q += 1;
        }
        emon.Port.CellsSet(ws, DIns, en);
        emon.Port.CellsSet(ws, DPos, en);
        return 0;
    }
    internal static int DfRun(emon.Port.Cells ws, emon.Port.Buf @out, int fin) {
        // Decide every position that has its lookahead (262 bytes), or, at the
        // end of the stream, every position left.
        int lim = 262;
        if (fin == 1) {
            lim = 1;
        }
        while ((emon.Port.CellsAt(ws, DAvail) - emon.Port.CellsAt(ws, DPos)) >= lim) {
            DfStep(ws, @out);
        }
        return 0;
    }
    public static int DfForce(emon.Port.Cells ws, int mode) {
        // TEST ONLY: 0 by cost (the default), 1 stored, 2 fixed, 3 dynamic.
        emon.Port.CellsSet(ws, DForce, mode);
        return 0;
    }
    public static int DfEnsure(emon.Port.Cells ws, emon.Port.Buf @out) {
        // Write the zlib header `78 01` once, before the first byte.
        if (emon.Port.CellsAt(ws, DStarted) == 0) {
            emon.Port.CellsSet(ws, DStarted, 1);
            emon.Port.BufPush(@out, 120);
            emon.Port.BufPush(@out, 1);
        }
        return 0;
    }
    public static int DfByte(emon.Port.Cells ws, emon.Port.Buf @out, int v) {
        // One input byte (`df-ensure` has been called). What the row writers of
        // emon.png feed it; the `df-write-` forms are loops over this.
        int av = emon.Port.CellsAt(ws, DAvail);
        emon.Port.CellsSet(ws, DRing + (av & 65535), v);
        emon.Port.CellsSet(ws, DAvail, av + 1);
        DfAdler(ws, v);
        DfRun(ws, @out, 0);
        return 0;
    }
    public static int DfWriteCells(emon.Port.Cells ws, emon.Port.Buf @out, emon.Port.Cells cells, int start, int end) {
        // Compress cells[start, end) (one byte per cell, the low eight bits).
        int i = start;
        DfEnsure(ws, @out);
        while (i < end) {
            DfByte(ws, @out, emon.Port.CellsAt(cells, i) & 255);
            i += 1;
        }
        return 0;
    }
    public static int DfWriteBlob(emon.Port.Cells ws, emon.Port.Buf @out, byte[] blob, int start, int end) {
        // Compress blob[start, end).
        int i = start;
        DfEnsure(ws, @out);
        while (i < end) {
            DfByte(ws, @out, emon.Port.BlobU8(blob, i));
            i += 1;
        }
        return 0;
    }
    public static int DfFinish(emon.Port.Cells ws, emon.Port.Buf @out) {
        // Decide what is left, write the final block and the Adler-32.
        DfEnsure(ws, @out);
        DfRun(ws, @out, 1);
        int en = emon.Port.CellsAt(ws, DAvail);
        int a = emon.Port.CellsAt(ws, DAda);
        int b = emon.Port.CellsAt(ws, DAdb);
        DfFlush(ws, @out, en, 1);
        DfAlign(ws, @out);
        emon.Port.BufPush(@out, ((b) >> (8)) & 255);
        emon.Port.BufPush(@out, b & 255);
        emon.Port.BufPush(@out, ((a) >> (8)) & 255);
        emon.Port.BufPush(@out, a & 255);
        return 0;
    }
}
